<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
const auth=useAuthStore(),router=useRouter(),mode=ref('login'),form=ref({username:'',password:'',displayName:''}),error=ref(''),busy=ref(false)
async function submit(){busy.value=true;error.value='';try{if(mode.value==='register'){await auth.register(form.value);mode.value='login'}else{await auth.login(form.value);router.push(auth.isAdmin?'/admin':'/')}}catch(e){error.value=e.message||'操作失败'}finally{busy.value=false}}
</script>
<template><div class="auth-page"><section class="auth-intro"><p class="eyebrow">VULNSCOPE ACCESS</p><h1>理解依赖，<br><span>再处理风险。</span></h1><p>普通用户扫描Maven项目并查看分析；管理员维护数据源与Spark任务。</p><div class="sequence"><span>HDFS</span><span>YARN</span><span>SPARK</span><span>MYSQL</span></div></section><form class="auth-form" @submit.prevent="submit"><p class="eyebrow">{{mode==='login'?'账户登录':'创建普通用户'}}</p><h2>{{mode==='login'?'欢迎回来':'注册账户'}}</h2><div class="field"><label>用户名</label><input v-model.trim="form.username" required minlength="4" autocomplete="username"></div><div v-if="mode==='register'" class="field"><label>显示名称</label><input v-model.trim="form.displayName" required maxlength="50"></div><div class="field"><label>密码</label><input v-model="form.password" type="password" required minlength="6" autocomplete="current-password"></div><p v-if="error" class="error">{{error}}</p><button class="btn primary" :disabled="busy">{{busy?'处理中…':mode==='login'?'登录':'注册'}}</button><button type="button" class="switch" @click="mode=mode==='login'?'register':'login'">{{mode==='login'?'没有账户？注册普通用户':'已有账户？返回登录'}}</button></form></div></template>
<style scoped>.auth-page{min-height:calc(100vh - 68px);display:grid;grid-template-columns:1.4fr 1fr}.auth-intro{background:#111;color:#fff;padding:70px;display:flex;flex-direction:column;justify-content:center}.auth-intro h1{font-size:clamp(52px,7vw,110px);line-height:.86;letter-spacing:-.07em;margin:10px 0 30px}.auth-intro h1 span{color:var(--red)}.auth-intro>p{max-width:500px;line-height:1.7;color:#bbb}.sequence{display:flex;margin-top:50px}.sequence span{border:1px solid #555;padding:10px 14px;font-size:11px}.auth-form{padding:70px;display:grid;align-content:center;gap:20px;max-width:560px}.auth-form h2{font-size:38px;margin:0 0 15px}.error{color:var(--red);margin:0}.switch{border:0;background:none;text-align:left;padding:0;text-decoration:underline}@media(max-width:800px){.auth-page{grid-template-columns:1fr}.auth-intro{padding:45px 25px}.auth-form{padding:40px 25px}}</style>
